import { IconArrowRight } from "@rhs-ui/icons";
import { WatchDemoHero } from "@rhs-ui/marketing/watch-demo-hero";
import { Button } from "@rhs-ui/primitives/button";

/* The product shot is drawn here so the demo needs no files: Kestrel's week view, in its dark theme. */
const week: [day: number, from: number, to: number, label: string, tone: 0 | 1 | 2][] = [
  [0, 9, 11, "Deep work: Q4 plan", 0], [1, 9, 10.5, "Deep work: API", 0], [2, 9, 11, "Deep work: Writing", 0], [3, 10, 12, "Deep work: Hiring", 0], [4, 9, 11, "Deep work: Roadmap", 0],
  [0, 11.5, 12, "Standup", 1], [0, 13, 15, "Design review", 1], [0, 15.5, 17, "Inbox and admin", 2],
  [1, 11, 12, "1:1 with Maya", 1], [1, 14, 16, "Workshop", 1],
  [2, 13, 14, "Lunch and a walk", 2], [2, 14, 15.5, "Sprint planning", 1],
  [3, 9, 10, "Standup and triage", 1], [3, 14, 15, "Customer call", 1],
  [4, 13, 14, "Demo day", 1], [4, 16, 17, "Weekly review", 2],
];

function poster(): string {
  const left = 330;
  const top = 176;
  const row = 52;
  const col = (1244 - left) / 5;
  const time = (hour: number) => `${Math.floor(hour)}:${hour % 1 ? "30" : "00"}`;
  let art = "<rect width='1280' height='720' fill='#161616'/><rect width='232' height='720' fill='#1b1b1b'/><path d='M232 0V720' stroke='#272727'/>";
  art += "<rect x='28' y='30' width='26' height='26' rx='7' fill='#ececec'/><path d='M37.5 36.5v13M37.5 43.5l8-7M41 41l5 8.5' stroke='#151515' stroke-width='2.4' fill='none' stroke-linecap='round' stroke-linejoin='round'/><text x='64' y='50' font-size='20' font-weight='600' fill='#ededed'>Kestrel</text>";
  ["Week", "Tasks", "Habits", "Insights"].forEach((name, index) => {
    const y = 104 + index * 44;
    if (index === 0) art += `<rect x='16' y='${y}' width='200' height='38' rx='9' fill='#2a2a2a'/>`;
    art += `<rect x='32' y='${y + 13}' width='12' height='12' rx='3' fill='none' stroke='${index === 0 ? "#ededed" : "#8c8c8c"}' stroke-width='1.8'/><text x='58' y='${y + 24}' font-size='15' font-weight='${index === 0 ? 600 : 500}' fill='${index === 0 ? "#ededed" : "#8c8c8c"}'>${name}</text>`;
  });
  art += "<text x='32' y='330' font-size='11' font-weight='600' letter-spacing='1.4' fill='#8c8c8c'>CALENDARS</text>";
  [["Work", "#ececec"], ["Personal", "#8c8c8c"], ["Team", "#5a5a5a"]].forEach(([name, dot], index) => {
    art += `<circle cx='38' cy='${362 + index * 34}' r='5' fill='${dot}'/><text x='56' y='${367 + index * 34}' font-size='15' fill='#dedede'>${name}</text>`;
  });
  art += "<text x='276' y='72' font-size='28' font-weight='600' letter-spacing='-0.5' fill='#ededed'>Week 43</text><text x='276' y='100' font-size='15' fill='#8c8c8c'>19 to 23 October</text>";
  art += "<text x='1180' y='82' font-size='15' font-weight='500' text-anchor='end' fill='#dedede'>Auto-plan</text><rect x='1196' y='64' width='48' height='26' rx='13' fill='#ececec'/><circle cx='1231' cy='77' r='9.5' fill='#151515'/>";
  ["Mon 19", "Tue 20", "Wed 21", "Thu 22", "Fri 23"].forEach((day, index) => {
    art += `<text x='${left + index * col + 12}' y='158' font-size='14' font-weight='600' fill='${index === 1 ? "#ededed" : "#8c8c8c"}'>${day}</text>`;
    if (index) art += `<path d='M${left + index * col} ${top - 8}V${top + 9 * row}' stroke='#272727'/>`;
  });
  for (let hour = 0; hour <= 9; hour++) {
    art += `<path d='M${left} ${top + hour * row}H1244' stroke='#272727'/>`;
    if (hour < 9) art += `<text x='${left - 14}' y='${top + hour * row + 14}' font-size='12' text-anchor='end' fill='#8c8c8c'>${9 + hour}:00</text>`;
  }
  for (const [day, from, to, label, tone] of week) {
    const x = left + day * col + 6;
    const y = top + (from - 9) * row + 2;
    const height = (to - from) * row - 4;
    const ink = tone === 0 ? "#151515" : "#dedede";
    art += `<rect x='${x}' y='${y}' width='${col - 12}' height='${height}' rx='8' fill='${tone === 0 ? "#ececec" : tone === 1 ? "#2f2f2f" : "#1e1e1e"}'${tone === 2 ? " stroke='#363636'" : ""}/>`;
    art += `<text x='${x + 12}' y='${height < 34 ? y + height / 2 + 5 : y + 22}' font-size='14' font-weight='600' fill='${ink}'>${label}</text>`;
    if (height > 44) art += `<text x='${x + 12}' y='${y + 40}' font-size='12' fill='${tone === 0 ? "#555" : "#8c8c8c"}'>${time(from)} to ${time(to)}</text>`;
  }
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1280 720' font-family='Segoe UI, Inter, system-ui, sans-serif'>${art}</svg>`;
  return "data:image/svg+xml;utf8," + encodeURIComponent(svg);
}

/* Eight seconds of the same week view filling itself in, as a small mp4 (960 by 540 and silent, so the captions carry the story). In your app: your own video file. */
const video = "data:video/mp4;base64,";

const captions =
  "data:text/vtt;charset=utf-8," +
  encodeURIComponent(
    "WEBVTT\n\n00:00.300 --> 00:02.000\nTurn on auto-plan.\n\n00:02.000 --> 00:04.000\nKestrel protects your focus time first,\n\n00:04.000 --> 00:05.500\nthen fits the meetings around it.\n\n00:05.500 --> 00:08.000\nYour week, planned before Monday starts.\n",
  );

export default function Demo(): React.JSX.Element {
  return (
    <div className="mx-auto max-w-6xl px-6">
      <WatchDemoHero
        title="Your week, planned before Monday starts."
        description="Kestrel reads your tasks and your calendar, protects the hours that matter and fits everything else around them."
        actions={
          <>
            <Button size="lg">
              Start a free trial
              <IconArrowRight />
            </Button>
            <Button size="lg" variant="outline">
              See pricing
            </Button>
          </>
        }
        poster={poster()}
        videoSrc={video}
        captionsSrc={captions}
        duration="0:08"
        playLabel="Watch it in 8 seconds"
        videoTitle="Kestrel plans a whole working week in eight seconds"
        transcriptHref="#transcript"
      />
    </div>
  );
}
